contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Drive contract and check property: only DEPOSITOR_ACCOUNT may call setL1BlockValues.
    // We take all parameters so the verifier can supply arbitrary values and call from arbitrary senders.
    function runTest(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        // Precondition: ensure caller is NOT the depositor so that a call from this address should revert under P.
        // We cannot read DEPOSITOR_ACCOUNT directly, but we know C exports it as a public constant, so read it.
        address depositor = c.DEPOSITOR_ACCOUNT();
        require(msg.sender != depositor, "test must be called from non-depositor to exercise property");

        // Attempt to call setL1BlockValues from this (non-depositor) address. Under P this must revert; under M it will succeed.
        bool reverted;
        // perform low-level call to capture success/failure without reverting the test itself
        (reverted, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        // The general rule: the call must fail (revert) when made by a non-depositor caller.
        // Note: reverted is 'success' boolean from low-level call; we assert it is false.
        assert(reverted == false);
    }

    // receive/fallback not needed but allowed by specification; omitted.
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition needed
        bool reverted;
        try c.setL1BlockValues(0,0,0,bytes32(0),0,bytes32(0),0,0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // In the original contract, the call reverts exactly when msg.sender is not the depositor.
        // We can't reference DEPOSITOR_ACCOUNT directly, so express the rule via reverted vs msg.sender equality
        // The rule: reverted == (msg.sender != address(c).DEPOSITOR_ACCOUNT) cannot be written because DEPOSITOR_ACCOUNT is a constant on c.
        // However the allowed observable is only revert flag and parameters; we have no params here, so assert that either the call reverted or not depending on caller:
        // Assert that if the call did NOT revert then msg.sender == tx.origin (sanity) — but that is not distinguishing mutant.
        // To capture the distinction, require that a call from the same caller twice has same revert behavior: calling again yields same reverted value.
        bool reverted2;
        try c.setL1BlockValues(1,1,1,bytes32(1),1,bytes32(1),1,1) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        // General rule: behavior (revert or not) of setL1BlockValues is independent of its arguments — only depends on caller; so both attempts must have same revert outcome.
        assert(reverted == reverted2);
    }
    receive() external payable {}
}

