pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: the number to attempt to set. We use a single fuzz param as required.
    function testFuzz_property(uint64 newNumber) public {
        // Keep domain wide; no restrictive assumes.

        // Scenario: the correct contract only allows DEPOSITOR_ACCOUNT to set values.
        // The mutant also allows address(this) (self-calls). We craft a self-call by deploying
        // a tiny helper that instructs the contract to call itself via a low-level call.
        // However we cannot modify C; instead we cause the call to originate from the contract
        // itself by making the contract perform an external call to itself. To do that we
        // deploy a helper that triggers c to call back into itself via a plain external call
        // using address(c).call(...). The helper will instruct c to perform that call by
        // invoking a specially-encoded function selector on c which we cannot add. Since
        // we cannot alter C's code, we instead perform the self-call directly from this test
        // by using address(c).call while setting msg.sender to address(c) via vm.prank.
        // vm.prank cannot set msg.sender to address(c) unless we control that address; but
        // Foundry provides vm.prank with an arbitrary address — however that address is
        // treated as EOA for the call origin and not as contract code. The mutant checks
        // only msg.sender == address(this) (the contract's own address), so to emulate a
        // call with msg.sender == address(c) we must perform a call that has that origin.
        // Foundry allows vm.prank(address) to set msg.sender to any address for the next call,
        // which is sufficient because the modifier inspects msg.sender only. We use that to
        // simulate a self-call: vm.prank(address(c)); (bool ok, ) = address(c).call(abi.encodeWithSignature(...) ).
        // The reference will still reject because only DEPOSITOR_ACCOUNT is allowed.

        // Prepare calldata for setL1BlockValues with our fuzzed newNumber and dummy other params.
        bytes memory data = abi.encodeWithSignature(
            "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
            newNumber, // _number
            uint64(block.timestamp), // _timestamp
            uint256(0), // _basefee
            bytes32(0), // _hash
            uint64(0), // _sequenceNumber
            bytes32(0), // _batcherHash
            uint256(0), // _l1FeeOverhead
            uint256(0)  // _l1FeeScalar
        );

        // 1) Call as the legitimate depositor: should succeed on both reference and mutant.
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        (bool ok1, ) = address(c).call(data);
        // ensure depositor call succeeded (both contracts should allow)
        assertTrue(ok1);
        // and number should now equal newNumber
        assertTrue(c.number() == newNumber);

        // 2) Now simulate a call that appears to come from address(c) itself (self-call).
        // The reference contract should reject this (only depositor allowed). The mutant
        // will accept it, changing number again. We capture whether the call succeeded.
        vm.prank(address(c));
        (bool ok2, ) = address(c).call(data);

        // General rule asserted: For ANY fuzzed newNumber, when a caller is address(c) (a self-call),
        // the reference C must NOT accept that and thus c.number() must remain equal to newNumber
        // only if ok2 is false. We assert the universal property: after the self-call attempt,
        // either the call failed (ok2 == false) and number is unchanged (still newNumber from depositor),
        // OR if call succeeded (ok2 == true) then this is a deviation (mutant) — but the single
        //assert must be true on the reference for ALL inputs. Since the reference will always reject
        // the self-call, ok2 will be false and number will remain equal to newNumber. We therefore assert that.
        assertTrue(!ok2 && c.number() == newNumber);
    }
}

