    C c;

    // Helper attacker that will cause a revert when touched via a state-dependent check.
    // We'll simulate an external call path by making C's onlyDepositor check require msg.sender == DEPOSITOR_ACCOUNT.
    // The difference arises if some operation after assignments reverts; to trigger a revert after some assignments
    // we create a helper that will revert when called. However, setL1BlockValues in C does not call external
    // addresses; the bug is observable if we cause the call to revert after some assignments via a proxy depositor
    // that reverts in its fallback after forwarding — to create a scenario where some intermediate state updates
    // happen in the callee before the revert. We'll implement a DepositorForwarder that first calls c.setL1BlockValues
    // but then reverts (so the whole tx reverts). To force different behavior between assigning timestamp early vs last,
    // we instead rely on the fact that if the depositor contract uses a try/catch or low-level call, behavior differs.
    // Simpler: we deploy a Depositor that in its fallback forwards the call to c using a low-level call and then reverts
    // after the low-level call's success — causing the outer transaction to revert while allowing the inner low-level call
    // to have completed its state changes in c. This differentiates ordering: if timestamp is assigned before the revert-causing
    // operation in the callee, it will be set; if it is assigned after, it won't.

    address constant DEPOSITOR_ACCOUNT = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public {
        c = new C();
    }

    // Fuzz parameters include the deciding timestamp and a boolean to choose whether the depositor-forwarder will revert after forwarding.
    // The fuzzer will try to find a case where the mutant leaves timestamp unchanged while the reference sets it.
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar, bool willRevertAfterForward) public {
        // Keep domain wide; restrict nothing except ensure the depositor-forwarder address equals the constant expected by C.
        // Deploy a DepositorForwarder bound to the hardcoded DEPOSITOR_ACCOUNT address by creating it from that address via vm.prank and create.
        // We need the depositor's address to be exactly DEPOSITOR_ACCOUNT; use vm.prank with an address that creates the contract so its address matches.

        // Compute a creator address such that the created contract will have address DEPOSITOR_ACCOUNT.
        // It's difficult to deterministically create that; instead, we cheat by using an intermediate factory: we will deploy a
        // DepositorForwarder and then use address aliasing by making C's DEPOSITOR_ACCOUNT constant equal to that address in the real system.
        // But we cannot change C. So instead we simulate calls by using vm.prank with the exact DEPOSITOR_ACCOUNT EOA and have the EOA
        // perform the call directly. To emulate the adversarial behaviour (a depositor that forwards then reverts), we deploy a
        // DepositorActor whose address equals the constant by using create2 with a chosen salt from a deployer address.

        // For simplicity and robustness in Foundry tests, we'll use vm.etch to put code at the DEPOSITOR_ACCOUNT address creating a
        // contract that first calls c via a low-level call and then conditionally reverts. vm.etch is not allowed per rules.
        // The allowed cheatcodes do not include vm.etch. Therefore we must instead deploy a proxy from an account that we control
        // and make C accept that address as depositor. But C's depositor is a hardcoded constant, so we must deploy the contract
        // from the exact address constant. We can do that by creating the Depositor contract using CREATE2 from a factory deployed
        // at an address we control. Using CREATE2 with a chosen salt and deployer we can craft the created address to match the constant.

        // Deploy factory from an address we control (vm.addr(1))
        address factoryCreator = vm.addr(1);
        vm.prank(factoryCreator);
        Factory f = new Factory();

        // Compute salt such that create2 yields the desired DEPOSITOR_ACCOUNT
        bytes32 salt = bytes32(uint256(uint160(DEPOSITOR_ACCOUNT)));
        address depositor = f.deploy{value:0}(salt, willRevertAfterForward, address(c));
        // Ensure we indeed deployed at the constant address
        assert(depositor == DEPOSITOR_ACCOUNT);

        // Now have the depositor forward the call and optionally revert after forwarding.
        // We'll call the depositor (which will forward the calldata to c via a low-level call), so from C's perspective msg.sender == depositor.

        // Build calldata for setL1BlockValues
        bytes memory data = abi.encodeWithSignature("setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)", _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        // Call the depositor which will forward to c and then possibly revert. We wrap in try/catch to allow the outer tx to continue so we can observe c.timestamp().
        bool ok;
        try ICaller(depositor).forward(data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: if the inner low-level call to c completed, the reference contract will have set timestamp == _timestamp.
        // The mutant that assigns timestamp last can leave timestamp unchanged when a later step reverts inside the depositor after the forward.
        // We assert that if the inner call succeeded (i.e., ok == true OR even if depositor reverted after forward the low-level call may still have succeeded),
        // then c.timestamp() == _timestamp for the reference; the mutant will sometimes fail this. We must assert a property that holds for the reference
        // for all inputs. The reference always sets timestamp to _timestamp whenever c's setL1BlockValues execution actually executed its assignments.
        // To detect that, we require that after calling the depositor.forward, c.timestamp() == _timestamp.

        // Single assertion required. Read c.timestamp() getter.
        assertTrue(c.timestamp() == _timestamp);
    }
}

interface ICaller { function forward(bytes calldata) external; }

contract Factory {
    function deploy(bytes32 salt, bool willRevertAfterForward, address target) external payable returns (address addr) {
        bytes memory bytecode = abi.encodePacked(
            type(DepositorForwarder).creationCode,
            abi.encode(willRevertAfterForward, target)
        );
        address deployed;
        assembly {
            deployed := create2(callvalue(), add(bytecode, 0x20), mload(bytecode), salt)
        }
        require(deployed != address(0), "deploy failed");
        return deployed;
    }
}

contract DepositorForwarder {
    bool public willRevertAfterForward;
    address public target;

    constructor(bool _willRevertAfterForward, address _target) {
        willRevertAfterForward = _willRevertAfterForward;
        target = _target;
    }

    // forward arbitrary calldata to target via low-level call
    function forward(bytes calldata data) external returns (bytes memory) {
        (bool success, bytes memory ret) = target.call(data);
        // keep the low-level call result but then optionally revert after forwarding
        if (willRevertAfterForward) {
            revert("DepositorForwarder: revert after forward");
        }
        require(success, "forward failed");
        return ret;
    }
}

